            (() => { const shell = document.currentScript.closest('[data-public-shell]'); const toggle = shell?.querySelector('[data-public-theme-toggle]'); if (!shell || !toggle) return; const storageKey = 'ministry-theme'; const legacyStorageKey = 'ministry-public-theme'; const setTheme = (theme) => { const dark = theme === 'dark'; window.applyMinistryTheme?.(dark ? 'dark' : 'light'); shell.classList.toggle('public-theme-dark', dark); toggle.setAttribute('aria-pressed', String(dark)); toggle.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode'); const label = toggle.querySelector('.workspace-theme-label'); if (label) label.textContent = dark ? 'Dark' : 'Light'; }; const savedTheme = localStorage.getItem(storageKey) ?? localStorage.getItem(legacyStorageKey); if (savedTheme) localStorage.setItem(storageKey, savedTheme); setTheme(savedTheme === 'dark' ? 'dark' : 'light'); toggle.addEventListener('click', () => { const theme = shell.classList.contains('public-theme-dark') ? 'light' : 'dark'; localStorage.setItem(storageKey, theme); setTheme(theme); }); window.addEventListener('storage', (event) => { if (event.key === storageKey) setTheme(event.newValue === 'dark' ? 'dark' : 'light'); }); shell.querySelector('[data-public-more]')?.addEventListener('click', () => shell.querySelector('[data-public-menu]')?.click()); })();
        </script>
    </div>
